  const TIMING = {"seconds":15,"reduceMotionSeconds":10,"fadeOut":0.6,"chequeAt":2.2,"countUp":1.6,"skipAfter":2,"signAt":4.35,"signFor":1};
  const WORDS = {"heading":"CHAMPIONS' CHEQUE","bank":"RALLYCADE","pay":"PAY","for":"FOR","payeeFallback":"The champion","signature":"RallyCade","signatureRole":"Tournament director","date":"DATE","number":"No. {serial}","words":"{xp} XP and {coins} coins","skipTV":"Raise a hand to continue"};
  const W = 1920, H = 1080;
  // StadiumResultScale.television(1920 x 1080): the phone's points to the stage's.
  const S = Math.max(0.8, Math.min(H / 430, W / 860));
